/** The issue page of the SPA (`GET /issues/{key}/view`, P1 gap G1): every `get` field plus the full detail (dates, author, children, custom fields, allowed statuses) and the ids an edit form sends back, read in one transaction so the parts agree. */
export type SpaIssue = {
  actions?: IssueActions | null;
  allowed_statuses?: Array<string> | null;
  assigned_to_id: string | null;
  /** null when unassigned. */
  assignee?: string | null;
  /** user | group (a group assignee is not a person). */
  assignee_kind?: string | null;
  /** Design 06 R-A9: the issue's own attachments (not its notes'), oldest first. In the full detail only when there are any. */
  attachments?: Array<AttachmentMeta> | null;
  /** Design 06 R-A11: the server keeps files (`OXLEDGER_FILES_DIR`); off, the page shows no upload controls. */
  attachments_enabled: boolean;
  author?: string | null;
  children?: Array<IssueBrief> | null;
  /** Field → citation_id of the whole field (`citations`). */
  citations?: Record<string, string> | null;
  created_at?: string | null;
  custom_fields?: Array<CustomFieldValue> | null;
  description?: string | null;
  /** Web app only: the description is an agent's (its last writer was an agent, or a person applied an agent's proposal; R-M3). The editor warns before a person rewrites it (design 06 §6.2). */
  description_by_agent?: boolean | null;
  /** With `description`: `markdown`, or `plain` for a description written before M2 and not rewritten since (design 06 R-M9). */
  description_format?: string | null;
  /** Web app only (never over MCP, design 06 R-M10): the description as sanitized HTML, references resolved for the caller. The only description field to put in the page as HTML. */
  description_html?: string | null;
  /** `include: ["dev"]`: pull requests that name this issue (§19.7), a read-only projection that may lag GitHub by minutes (`synced_at`). */
  dev?: IssueDev | null;
  due_date?: string | null;
  /** Decimal string such as "1.5"; null when not set. */
  estimated_hours?: string | null;
  /** The milestone (`fixed_version_id`); null when none. */
  fixed_version?: VersionBrief | null;
  /** Contract 05 §3.6.3: full detail only, when rules published with `accept_and_mark` found this issue breaking them: the rule ids. The next write that passes the rules clears them. */
  form_rule_marks?: Array<string> | null;
  is_private?: boolean | null;
  key: string;
  /** The latest domain activity the caller can see (not `updated_at`, which also moves for notes the caller cannot read). */
  last_activity_at?: string | null;
  lock_version?: number | null;
  parent?: string | null;
  priority?: string | null;
  priority_id: string | null;
  project?: string | null;
  project_id: string;
  /** The current project key (the key prefix). */
  project_key: string;
  recent_events?: RecentEvents | null;
  recent_notes?: RecentNotes | null;
  /** Set when the requested key is an old key of a moved issue. */
  requested_key?: string | null;
  /** People only (contract 05 §3.5.4): the visible time on this issue; null when the caller cannot read time in the project. Agents asking for it get `invalid_argument` (`details.reason = "unavailable_to_agent"`). */
  spent_hours?: string | null;
  start_date?: string | null;
  status?: string | null;
  status_category?: string | null;
  status_id: string;
  /** When the issue last entered its current status (a transition that changed nothing does not count); the creation time if it never changed. null when the history is missing or redacted (then status_since_known is false). */
  status_since?: string | null;
  status_since_known?: boolean | null;
  subject?: string | null;
  tracker?: string | null;
  tracker_id: string;
  /** Contract 05 §3.4: `pending`, `snoozed`, `accepted`, `declined`, `duplicate`; null when the issue never entered the Triage inbox. */
  triage?: string | null;
  /** get_many: left out to keep the response small; call `get` for this key. */
  truncated?: boolean;
  updated_at?: string | null;
};

